const candidateSkin = process.env.MX_TEST_SKIN || 'style2';
const {chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');
const BASE=process.env.MX_AUDIT_URL||'http://127.0.0.1:5183';const CHROME=process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
(async()=>{const browser=await chromium.launch({executablePath:CHROME,headless:true});const p=await browser.newPage({viewport:{width:1200,height:1200}});const out=process.env.MX_OUTPUT_DIR||'docs/styles/'+candidateSkin+'/implementation/round1/interactions';fs.mkdirSync(out,{recursive:true});const results=[];const errors=[];p.on('pageerror',e=>errors.push(String(e)));async function open(q){await p.goto(BASE+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin:candidateSkin,layout:'balanced',scene:'figma',width:440,height:782,...q}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:45000})}
for(const layout of ['original','balanced','classic','oval'])for(const [w,h]of [[440,782],[375,500],[320,400]]){await open({layout,width:w,height:h,scene:'media-video',cards:6});const metrics=await p.evaluate(()=>{const r=document.querySelector('#audit-stage').getBoundingClientRect();const list=[...document.querySelectorAll('.mx-nav-button')];return list.map(e=>{const b=e.getBoundingClientRect();return {action:e.dataset.action,w:b.width,h:b.height,inside:b.left>=r.left-.5&&b.right<=r.right+.5&&b.top>=r.top&&b.bottom<=r.bottom}})});results.push({test:'six navigation bounds',layout,w,h,pass:metrics.length===6&&metrics.every(b=>b.inside&&b.w>=43.9&&b.h>=43.9),metrics});}
await open({scene:'media-voice'});const mic=p.locator('.mx-nav-button[data-action=voice]');const before=await mic.getAttribute('aria-pressed');await mic.click();await p.waitForTimeout(50);results.push({test:'voice toggle',before,after:await mic.getAttribute('aria-pressed'),pass:before!==await mic.getAttribute('aria-pressed')});
await open({});await p.locator('.mx-operation-raise').click();await p.locator('.mx-raise-range').press('ArrowUp');const v=await p.locator('.mx-raise-range').inputValue();await p.locator('.mx-raise-confirm').click();results.push({test:'raise submit',value:v,log:await p.locator('#audit-log').innerText(),pass:(await p.locator('#audit-log').innerText()).includes('本地操作成功：加注')});
await open({});await p.locator('.mx-operation-raise').click();await p.locator('.mx-operation-cancel').click();results.push({test:'raise cancel',pass:await p.locator('.mx-operation').getAttribute('data-mode')==='actions'});
await open({});await p.locator('.mx-nav-button[data-action=report]').click();results.push({test:'report click',pass:await p.locator('.mx-record-overlay:not([hidden])').count()>0});
await open({});await p.locator('.mx-menu').click();await p.locator('.mx-menu-item[data-menu-action=UITexas_Setting]').click();results.push({test:'settings click',pass:await p.locator('.mx-settings-overlay:not([hidden])').isVisible()});
await open({orientation:'auto',width:844,height:440,scene:'media-video'});await p.locator('#audit-stage').screenshot({path:out+'/landscape.png'});
await open({scene:'media-video',width:320,height:400,cards:6});await p.locator('#audit-stage').screenshot({path:out+'/mini-video-sixcards.png'});
fs.writeFileSync(out+'/results.json',JSON.stringify({results,errors},null,2));console.log(JSON.stringify({results,errors},null,2));if(errors.length||results.some(r=>!r.pass))process.exitCode=1;await browser.close();})();
